<?php require_once __DIR__.'/config/config.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');verify_csrf();$target=(int)($_POST['user_id']??0);$me=current_user_id();if($target===$me||$target<1)redirect('index.php');$s=$conn->prepare('SELECT id FROM users WHERE id=?');$s->bind_param('i',$target);$s->execute();if(!$s->get_result()->fetch_row())redirect('index.php');$s=$conn->prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?');$s->bind_param('ii',$me,$target);$s->execute();if($s->get_result()->fetch_row()){$s=$conn->prepare('DELETE FROM follows WHERE follower_id=? AND following_id=?');$s->bind_param('ii',$me,$target);$s->execute();}else{$s=$conn->prepare('INSERT IGNORE INTO follows(follower_id,following_id) VALUES(?,?)');$s->bind_param('ii',$me,$target);$s->execute();notify_user($conn,$target,$me,'follow');}$s=$conn->prepare('SELECT username FROM users WHERE id=?');$s->bind_param('i',$target);$s->execute();$u=$s->get_result()->fetch_assoc();redirect('profile.php?u='.rawurlencode($u['username']));?>